"use client"

import * as React from "react"
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Badge } from "./badge"

function Tabs({
  className,
  orientation = "horizontal",
  onValueChange,
  ...props
}: TabsPrimitive.Root.Props) {
  // The panel enters with a short fade only once the user has switched tabs: the first paint
  // (page load, LCP) never fades. Set on a change through the tabs or a change of a controlled value.
  const [switched, setSwitched] = React.useState(false)
  const lastValue = React.useRef(props.value)
  React.useEffect(() => {
    if (lastValue.current !== props.value) {
      lastValue.current = props.value
      setSwitched(true)
    }
  }, [props.value])
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      data-switched={switched ? "" : undefined}
      onValueChange={(value, details) => {
        setSwitched(true)
        onValueChange?.(value, details)
      }}
      // Passed on as well, so Base UI knows it too: the arrow keys follow the
      // axis (↑/↓ when vertical), the list says aria-orientation, and the
      // indicator measures the right edge.
      orientation={orientation}
      data-orientation={orientation}
      className={cn(
        "group/tabs flex gap-4 data-horizontal:flex-col data-vertical:flex-row data-vertical:items-start data-vertical:gap-4",
        className
      )}
      {...props}
    />
  )
}

/**
 * Two looks, both straight from the Figma Tab Bar page, horizontal or — with
 * `orientation="vertical"` on Tabs — stacked as a side navigation next to the
 * panel:
 *
 * - `default` is the "Tab Button" row — every tab is its own bordered button
 *   and the active one fills with the indigo tint. No track behind them.
 * - `line` is "Tab Item" — bare labels with an indigo underline under the
 *   active one, the shape that sits above a page's content.
 *
 * Vertical: `default` stacks full-width buttons with the label at the start;
 * `line` draws a rail on the left with the indicator gliding along it.
 *
 * The pill-in-a-grey-track control is a different component in Figma
 * ("Segmented Control") and a different one here: `Segment`.
 */
// Too many tabs for the width (a phone): the row scrolls sideways instead of
// pushing the page wider.
const tabsListVariants = cva(
  "group/tabs-list inline-flex w-fit max-w-full items-center text-muted-foreground data-[orientation=horizontal]:overflow-x-auto data-[orientation=horizontal]:[scrollbar-width:none] data-[orientation=horizontal]:[&::-webkit-scrollbar]:hidden [&>[data-slot=tabs-trigger]]:shrink-0 data-[orientation=vertical]:h-fit data-[orientation=vertical]:shrink-0 data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch",
  {
    variants: {
      variant: {
        // The row scrolls sideways (overflow-x clips the other axis too), so the 2 px focus ring of a
        // bordered tab needs room: 2 px of padding on every side, taken back with a -2 px margin and
        // content-box sizing, so the row keeps the exact height and width it had.
        default: "gap-2 data-[orientation=horizontal]:m-[-2px] data-[orientation=horizontal]:box-content data-[orientation=horizontal]:p-[2px] data-[orientation=vertical]:gap-1",
        // Horizontal: a 1 px grey baseline under the whole row (Figma Tab Bar),
        // drawn as an inset shadow so it stays inside the scroll box and the
        // 2 px indicator, painted above it, covers it: one line, no gap.
        line: "gap-6 data-[orientation=horizontal]:w-full data-[orientation=horizontal]:shadow-[inset_0_-1px_0_var(--border)] data-[orientation=vertical]:gap-0 data-[orientation=vertical]:border-s data-[orientation=vertical]:border-border",
      },
      // The Button heights, from the density tokens: compact 32/36/40,
      // data-density="comfortable" 36/40/44 (Figma Tab Button regular/medium/large).
      size: {
        // Horizontal: the row has the height and every tab fills it.
        // Vertical: each tab takes the height itself (--tab-h).
        sm: "[--tab-h:var(--control-sm)] data-[orientation=horizontal]:h-(--tab-h) [&_[data-slot=tabs-trigger]]:text-sm",
        md: "[--tab-h:var(--control-md)] data-[orientation=horizontal]:h-(--tab-h) [&_[data-slot=tabs-trigger]]:text-sm",
        lg: "[--tab-h:var(--control-lg)] data-[orientation=horizontal]:h-(--tab-h) [&_[data-slot=tabs-trigger]]:text-sm",
      },
      shape: {
        rounded: "[&_[data-slot=tabs-trigger]]:rounded-md",
        pill: "[&_[data-slot=tabs-trigger]]:rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "sm",
      shape: "rounded",
    },
  }
)

// wrap: a horizontal row breaks onto more rows instead of scrolling sideways (phones). Every tab keeps the row
// height (--tab-h); the line variant's rows sit flush, so its grey baseline stays under the last row.
const TABS_WRAP =
  "data-[orientation=horizontal]:h-auto data-[orientation=horizontal]:flex-wrap data-[orientation=horizontal]:overflow-visible data-[variant=line]:data-[orientation=horizontal]:gap-y-0"

function TabsList({
  className,
  variant = "default",
  size = "sm",
  shape = "rounded",
  wrap = false,
  children,
  ...props
}: TabsPrimitive.List.Props &
  VariantProps<typeof tabsListVariants> & {
    /** A horizontal row of tabs wraps onto more rows when it is wider than its container, instead of scrolling sideways. */
    wrap?: boolean
  }) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      data-size={size}
      data-wrap={wrap ? "" : undefined}
      className={cn("relative", tabsListVariants({ variant, size, shape }), wrap && TABS_WRAP, className)}
      {...props}
    >
      {children}
    </TabsPrimitive.List>
  )
}

/** Base length (px) the indicator is scaled from; any constant works. */
const INDICATOR_BASE = 100

/**
 * The underline of the `line` variant. Base UI measures the active tab; the
 * indicator follows it with `translate` and `scale` only (M2), from a fixed
 * 100 px base, so it glides from one label to the next on the compositor.
 * Before hydration the --active-tab-* variables Base UI's inline script sets
 * place it (width/height from the variables, no transition).
 */
function TabsIndicator({ className, style, ...props }: TabsPrimitive.Indicator.Props) {
  // The first measured position must not animate from the pre-hydration box.
  const positioned = React.useRef(false)
  return (
    <TabsPrimitive.Indicator
      data-slot="tabs-indicator"
      renderBeforeHydration
      className={cn(
        "pointer-events-none absolute z-0 bg-primary transition-transform duration-base ease-entrance motion-reduce:transition-none",
        // Horizontal: flush with the list's bottom edge, covering the baseline.
        "group-data-[orientation=horizontal]/tabs-list:bottom-0 group-data-[orientation=horizontal]/tabs-list:left-0 group-data-[orientation=horizontal]/tabs-list:h-0.5 group-data-[orientation=horizontal]/tabs-list:w-(--active-tab-width) group-data-[orientation=horizontal]/tabs-list:translate-x-(--active-tab-left) group-data-[orientation=horizontal]/tabs-list:origin-left",
        // Vertical: sits on the rail (the list's left border), covering it.
        "group-data-[orientation=vertical]/tabs-list:top-0 group-data-[orientation=vertical]/tabs-list:-left-px group-data-[orientation=vertical]/tabs-list:h-(--active-tab-height) group-data-[orientation=vertical]/tabs-list:w-0.5 group-data-[orientation=vertical]/tabs-list:translate-y-(--active-tab-top) group-data-[orientation=vertical]/tabs-list:origin-top",
        className
      )}
      style={(state) => {
        const own = typeof style === "function" ? style(state) : style
        const pos = state.activeTabPosition
        const size = state.activeTabSize
        if (!pos || !size) return own
        const first = !positioned.current
        positioned.current = true
        const placed: React.CSSProperties =
          state.orientation === "vertical"
            ? { height: INDICATOR_BASE, translate: `0 ${pos.top}px`, scale: `1 ${size.height / INDICATOR_BASE}` }
            : { width: INDICATOR_BASE, translate: `${pos.left}px 0`, scale: `${size.width / INDICATOR_BASE} 1` }
        return { ...placed, ...(first ? { transition: "none" } : null), ...own }
      }}
      {...props}
    />
  )
}

function TabsTrigger({
  className,
  count,
  children,
  ...props
}: TabsPrimitive.Tab.Props & {
  /** A count after the label (an indigo pill), shown on the active tab only. */
  count?: number
}) {
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-trigger"
      className={cn(
        "group/tab relative z-10 inline-flex items-center justify-center gap-2 font-medium whitespace-nowrap transition-colors duration-fast ease-move",
        "text-text-secondary hover:text-foreground",
        // Focus (owner rule 31 Oct 2026): the bordered Tab Button gets the shared focus-ring (indigo border,
        // 2 px indigo-300 ring on it); the borderless line tab draws the same 2 px ring inside.
        "outline-none group-data-[variant=default]/tabs-list:focus-ring group-data-[variant=line]/tabs-list:focus-visible:outline-2 group-data-[variant=line]/tabs-list:focus-visible:outline-solid group-data-[variant=line]/tabs-list:focus-visible:-outline-offset-2 group-data-[variant=line]/tabs-list:focus-visible:outline-(color:--indigo-300)",
        "disabled:pointer-events-none disabled:text-text-tertiary aria-disabled:pointer-events-none aria-disabled:text-text-tertiary",
        "group-data-[orientation=horizontal]/tabs-list:h-full group-data-[orientation=horizontal]/tabs-list:group-data-[wrap]/tabs-list:h-(--tab-h) group-data-[orientation=vertical]/tabs-list:h-(--tab-h) group-data-[orientation=vertical]/tabs-list:w-full group-data-[orientation=vertical]/tabs-list:justify-start",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        // Tab Button: bordered, filling with the indigo tint when active.
        "group-data-[orientation=horizontal]/tabs-list:group-data-[variant=default]/tabs-list:flex-1 group-data-[variant=default]/tabs-list:border group-data-[variant=default]/tabs-list:border-border group-data-[variant=default]/tabs-list:bg-card group-data-[variant=default]/tabs-list:px-4",
        // Figma Tab Button: hover bg-page, pressed bg-subtle; selected is the indigo tint with an indigo-300 border
        // that stays tinted on hover and goes bg-subtle while pressed.
        "group-data-[variant=default]/tabs-list:hover:bg-bg-page group-data-[variant=default]/tabs-list:active:bg-bg-subtle",
        "group-data-[variant=default]/tabs-list:data-active:border-(color:--indigo-300) group-data-[variant=default]/tabs-list:data-active:bg-tint-indigo group-data-[variant=default]/tabs-list:data-active:text-tint-text-indigo group-data-[variant=default]/tabs-list:data-active:hover:bg-tint-indigo group-data-[variant=default]/tabs-list:data-active:active:bg-bg-subtle",
        // A badge or counter at the end of a bordered tab (owner 15 Nov 2026): as far from the right edge as from the top
        // and bottom, (tab height - 2 px border - 20 px badge) / 2; label to badge stays the 8 px gap.
        "group-data-[variant=default]/tabs-list:has-[>[data-slot=badge]:last-child]:pe-[calc((var(--tab-h)-2px-1.25rem)/2)] group-data-[variant=default]/tabs-list:has-[>[data-slot=badge-counter]:last-child]:pe-[calc((var(--tab-h)-2px-1.25rem)/2)] group-data-[variant=default]/tabs-list:data-active:has-[>[data-slot=tabs-trigger-count]:last-child]:pe-[calc((var(--tab-h)-2px-1.25rem)/2)]",
        // Tab Item: nothing but the label and the underline below it.
        "group-data-[variant=line]/tabs-list:bg-transparent group-data-[variant=line]/tabs-list:px-0 group-data-[variant=line]/tabs-list:data-active:text-text-link",
        // Vertical line: the label sits right of the rail.
        "group-data-[orientation=vertical]/tabs-list:group-data-[variant=line]/tabs-list:px-4",
        // The underline belongs to the tab: the grey baseline (or rail) never moves or changes size, and switching
        // tabs only swaps which tab shows its indigo 2 px line. No gliding indicator.
        "group-data-[variant=line]/tabs-list:after:pointer-events-none group-data-[variant=line]/tabs-list:after:absolute group-data-[variant=line]/tabs-list:after:bg-primary group-data-[variant=line]/tabs-list:after:opacity-0 group-data-[variant=line]/tabs-list:after:transition-opacity group-data-[variant=line]/tabs-list:after:duration-fast group-data-[variant=line]/tabs-list:after:ease-entrance motion-reduce:group-data-[variant=line]/tabs-list:after:transition-none group-data-[variant=line]/tabs-list:data-active:after:opacity-100",
        // Line variant: an inactive tab shows a grey underline on hover (Tab Item), the active one keeps the indigo one.
        "group-data-[variant=line]/tabs-list:not-data-active:hover:after:bg-border-control group-data-[variant=line]/tabs-list:not-data-active:hover:after:opacity-100",
        "group-data-[orientation=horizontal]/tabs-list:group-data-[variant=line]/tabs-list:after:inset-x-0 group-data-[orientation=horizontal]/tabs-list:group-data-[variant=line]/tabs-list:after:bottom-0 group-data-[orientation=horizontal]/tabs-list:group-data-[variant=line]/tabs-list:after:h-0.5",
        "group-data-[orientation=vertical]/tabs-list:group-data-[variant=line]/tabs-list:after:inset-y-0 group-data-[orientation=vertical]/tabs-list:group-data-[variant=line]/tabs-list:after:-left-px group-data-[orientation=vertical]/tabs-list:group-data-[variant=line]/tabs-list:after:w-0.5",
        className
      )}
      {...props}
    >
      {children}
      {count !== undefined && (
        <span data-slot="tabs-trigger-count" className="hidden group-data-active/tab:inline-flex">
          <Badge color="indigo" badgeStyle="light" shape="pill">
            {count}
          </Badge>
        </span>
      )}
    </TabsPrimitive.Tab>
  )
}

function TabsContent({ className, ...props }: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      className={cn("flex-1 rounded-md text-sm outline-none group-data-switched/tabs:animate-in group-data-switched/tabs:fade-in-0 group-data-switched/tabs:slide-in-from-bottom-1 group-data-switched/tabs:duration-base group-data-switched/tabs:ease-entrance motion-reduce:animate-none focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--indigo-300)", className)}
      {...props}
    />
  )
}

export { Tabs, TabsList, TabsTrigger, TabsIndicator, TabsContent, tabsListVariants }

import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon, type IconName } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { opticalCenter } from "@/lib/optical-center"

// Hex per color - the same hue set as the Figma "Badge" component (600 step
// of each Primitives scale). Kept as plain hex (not CSS vars) so color-mix()
// below can compute the light/opacity variants at runtime.
const BADGE_COLORS = {
  blue: "#12AFF0",
  green: "#1AD598",
  red: "#F47690",
  yellow: "#FACA4A",
  purple: "#A584F3",
  indigo: "#555CF3",
  pink: "#FE6BBA",
  orange: "#F3654A",
  alternative: "#6E6D86",
  grey: "#A2A3A3",
  black: "#000000",
  white: "#FFFFFF",
} as const

type BadgeColor = keyof typeof BADGE_COLORS

const badgeVariants = cva(
  cn(
    "group/badge inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border border-transparent font-semibold whitespace-nowrap transition duration-fast ease-entrance [&>svg]:pointer-events-none",
    // Rendered as a button or link, a badge is a chip: it answers the pointer
    // and the keyboard like any other control.
    //
    // The hover cue is a ring in the label's own colour, not a brightness
    // filter. brightness() moves fill and label together, and because the label
    // polarity differs per colour — a deep hue on a bright fill in light mode,
    // white on indigo and alternative in dark mode — no single factor is safe in
    // both directions: brightness-95/125 measured 3.40:1 on dark alternative,
    // 3.81:1 on dark indigo and 4.44:1 on light orange, and the factors that
    // clear AA everywhere (98%/106%) are too small to see. A ring changes
    // nothing about the label's backdrop, so contrast is unaffected whatever the
    // colour. See /scripts/contrast-audit.mjs, which reads this hover treatment
    // out of this file.
    "[&:is(button,a)]:cursor-pointer [&:is(button,a)]:outline-none [&:is(button,a)]:hover:ring-2 [&:is(button,a)]:hover:ring-current/30 [&:is(button,a)]:active:scale-95 motion-reduce:[&:is(button,a)]:active:scale-100 [&:is(button,a)]:focus-ring"
  ),
  {
    variants: {
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        sm: "h-5 gap-1 px-2 text-xs [&>svg]:size-3!",
        md: "h-6 gap-1.5 px-2.5 text-sm [&>svg]:size-3.5!",
      },
    },
    defaultVariants: {
      shape: "rounded",
      size: "sm",
    },
  }
)

type BadgeStyle = "plain" | "light" | "light_border" | "border_color" | "border_grey" | "ghost"

// Hues that have a Figma tint pair (`tint/<hue>` surface + `tint-text/<hue>`
// text, both mode-aware). Grey, black and white have none and fall back to
// color-mix() below.
const TINTED: readonly BadgeColor[] = ["blue", "green", "red", "yellow", "purple", "indigo", "pink", "orange", "alternative"]

// Text on a solid fill: white on every hue (owner decision Nov 17 2026: white text on solid colour, never black). The one exception is the white badge, whose fill is white itself, so it keeps black text.
const SOLID_TEXT_DARK: readonly BadgeColor[] = ["white"]

// The two achromatic badges are spelled out in Figma rather than derived: a
// black badge pales to the grey scale, a white one to the surface grey — a
// color-mix of #000 or #FFF lands somewhere else entirely.
// `text` sits on the badge's own fill; `ink` sits on the card or on nothing at
// all (outline, ghost), so it has to follow the mode — pure black there would
// vanish into a dark card.
const ACHROMATIC: Partial<Record<BadgeColor, { bg: string; text: string; ink: string; border: string }>> = {
  black: { bg: "var(--dark-200)", text: "#000000", ink: "var(--foreground)", border: "var(--dark-300)" },
  white: { bg: "var(--muted)", text: "var(--foreground)", ink: "var(--foreground)", border: "var(--border-control)" },
  // Grey has no tint pair; its 600 hue (#A2A3A3) is a fill colour, too pale
  // for a label on white. Text takes the tertiary text token instead (AA in
  // both modes), the surface keeps the grey hue.
  grey: {
    // 10 % (not 16 %) keeps the tertiary text at 4.7:1 on the surface — 16 % measured 4.46:1
    bg: "color-mix(in srgb, #A2A3A3 10%, var(--card))",
    text: "var(--text-tertiary)",
    ink: "var(--text-tertiary)",
    border: "var(--border-control)",
  },
}

// Figma Badge / Plain: the label sits on the page, not on a tint, so it takes the semantic text token
// (link, success, error) where one exists and the hue's tint-text everywhere else.
const GHOST_TEXT: Partial<Record<BadgeColor, string>> = {
  indigo: "var(--text-link)",
  green: "var(--text-success)",
  red: "var(--text-error)",
}

function styleToCss(color: BadgeColor, style: BadgeStyle) {
  const hex = BADGE_COLORS[color]
  const tinted = TINTED.includes(color)
  const flat = ACHROMATIC[color]
  const tintBg = flat ? flat.bg : tinted ? `var(--tint-${color})` : `color-mix(in srgb, ${hex} 12%, var(--card))`
  const tintText = flat ? flat.text : tinted ? `var(--tint-text-${color})` : hex === "#FFFFFF" ? "#000000" : hex
  const inkText = flat ? flat.ink : tintText
  const tintBorder = flat
    ? flat.border
    : tinted
      ? `color-mix(in srgb, var(--tint-text-${color}) 40%, var(--card))`
      : `color-mix(in srgb, ${hex} 40%, var(--card))`
  // Figma Badge / Outline: the rim is the tint-text token of the hue itself (a variable, not a blend).
  const outlineBorder = flat ? flat.border : tinted ? `var(--tint-text-${color})` : tintBorder
  switch (style) {
    case "plain":
      return {
        background: hex,
        borderColor: hex,
        color: SOLID_TEXT_DARK.includes(color) ? "#000000" : "#FFFFFF",
      }
    case "light":
      return {
        background: tintBg,
        borderColor: "transparent",
        color: tintText,
      }
    case "light_border":
      return {
        background: tintBg,
        borderColor: outlineBorder,
        color: tintText,
      }
    case "border_color":
      return {
        background: "var(--card)",
        borderColor: tintBorder,
        color: inkText,
      }
    case "border_grey":
      return {
        background: "var(--card)",
        borderColor: "var(--border)",
        color: inkText,
      }
    case "ghost":
      return {
        background: "transparent",
        borderColor: "transparent",
        color: GHOST_TEXT[color] ?? inkText,
      }
  }
}

function Badge({
  className,
  shape,
  size = "sm",
  color = "blue",
  badgeStyle = "plain",
  style,
  render,
  dot,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: useRender.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    color?: BadgeColor
    badgeStyle?: BadgeStyle
    dot?: boolean
    onRemove?: () => void
    removeLabel?: string
  }) {
  // Don't render the remove button when the badge is a button/link (`render`),
  // as that would nest interactive elements.
  const removeButton = onRemove && render === undefined ? (
    <button
      type="button"
      data-slot="badge-remove"
      aria-label={removeLabel}
      onClick={onRemove}
      className="relative -me-1 ms-0.5 inline-flex size-4 shrink-0 cursor-pointer after:absolute after:-inset-1 after:content-['']  items-center justify-center rounded-full outline-none transition duration-fast ease-entrance hover:bg-current/15 active:scale-90 motion-reduce:active:scale-100 focus-ring"
    >
      <Icon name="close" aria-hidden="true" className="size-3" />
    </button>
  ) : null

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        className: cn(badgeVariants({ shape, size }), className),
        style: { ...styleToCss(color, badgeStyle), ...style },
        children: (
          <>
            {dot && (
              <span
                data-slot="badge-dot"
                aria-hidden="true"
                className="size-1.5 shrink-0 rounded-full bg-current"
              />
            )}
            {opticalCenter(children)}
            {removeButton}
          </>
        ),
      },
      props
    ),
    render,
    state: {
      slot: "badge",
      color,
      badgeStyle,
      size,
      ...(dot ? { dot: true } : {}),
    },
  })
}

type BadgeCounterTone = "neutral" | "brand" | "danger"

const BADGE_COUNTER_TONE_CLASSES: Record<BadgeCounterTone, string> = {
  neutral: "bg-bg-subtle text-foreground data-[zero]:text-text-tertiary",
  brand: "bg-primary text-primary-foreground",
  danger: "bg-destructive text-destructive-foreground",
}

const BADGE_COUNTER_KIND_CLASSES: Record<"inline" | "overlay", string> = {
  inline: "h-5 min-w-5 px-1.5 text-xs font-medium",
  overlay: "absolute top-0 right-0 z-10 h-4 min-w-4 translate-x-1/2 -translate-y-1/2 px-1 text-[11px] font-medium ring-2 ring-card",
}

function BadgeCounter({
  count,
  max = 99,
  tone = "neutral",
  overlay = false,
  hideZero,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  count: number
  max?: number
  tone?: BadgeCounterTone
  overlay?: boolean
  hideZero?: boolean
}) {
  const resolvedHideZero = hideZero ?? overlay
  const shown = Math.max(0, Math.trunc(count))
  if (shown <= 0 && resolvedHideZero) return null
  const text = shown > max ? `${max}+` : String(shown)

  return (
    <span
      data-slot="badge-counter"
      data-tone={tone}
      data-kind={overlay ? "overlay" : "inline"}
      data-zero={shown === 0 ? "" : undefined}
      className={cn(
        "inline-flex items-center justify-center rounded-full tabular-nums leading-none whitespace-nowrap select-none",
        BADGE_COUNTER_KIND_CLASSES[overlay ? "overlay" : "inline"],
        BADGE_COUNTER_TONE_CLASSES[tone],
        className
      )}
      {...props}
    >
      <span className="optical-center">{text}</span>
    </span>
  )
}

